/**
 * Reference-surface types for the v2 catalog.
 *
 * A *catalog fragment* describes one entity's **reference surface** — exactly
 * what a referencing entity file needs to name it safely, and nothing more.
 * For a behavioral entity (automation / agent / skill) that is just its
 * **handle** (the join key, resolved to an id at deploy time) plus its display
 * name for readability. **No id appears in the catalog** — identity lives in
 * state (`src/deploy/state`).
 *
 * The `__kind` discriminant lets a builder's reference parameter accept exactly
 * the right kind of handle (`runAutomation(ref: AutomationRef)`) and makes the
 * fragment self-describing. These are the shapes the fragment renderer emits
 * and the (forthcoming) builders consume — the single shared contract.
 *
 * Two groups of kinds share this shape. **Behavioral entities**
 * (automation/agent/skill) are author-managed: imported reference-only, then
 * deployed. **Reference-surface entities** — an app's *fields* and *search
 * tables*, and org-owned *cloud links* / AI provider *connectors* — are never
 * deployed through v2; they're imported so a builder can point at them by typed
 * handle (`app.fields.severity`, `connectors.bedrockSonnet`). Field refs carry
 * a little extra schema (`fieldType`) for authoring-time type safety; that
 * schema is authoring-only — at the wire boundary `resolvePayload` replaces the
 * whole token with the resolved id, discarding it.
 */
/** Exact Snowflake signature types used to disambiguate overloaded procedures. */
export const PROCEDURE_PARAMETER_TYPES = [
    "BOOLEAN", "DATE", "DATETIME", "DECIMAL", "HANDLE", "JSON", "LONG", "TEXT", "UUID",
];
/** Platform-owned user attributes accepted by user-search task filters. */
export const USER_FIELD_KEYS = ["firstName", "email", "jobTitle", "lastName"];
/**
 * Which scope resolves a kind's id at deploy:
 *   - `"app"`      — the app's v2 state (app-owned entities + fields/tables);
 *   - `"org"`      — the org's v2 state (cloud links, connectors);
 *   - `"registry"` — the app registry (`apps.v2.json`), for app/element self-refs
 *     (`app` / `element`), keyed by handle → id rather than a state binding.
 */
export const REF_SCOPE = {
    automation: "app",
    agent: "app",
    "agent-evaluation": "app",
    chart: "app",
    dashboard: "app",
    widget: "app",
    skill: "app",
    "visual-flow": "app",
    approvalChain: "app",
    table: "org",
    tableColumn: "org",
    cloudLink: "org",
    storedFunction: "org",
    procedure: "org",
    field: "app",
    searchTable: "app",
    datamine: "app",
    documentModel: "app",
    documentModelField: "app",
    connector: "org",
    aiProvider: "org",
    category: "org",
    group: "org",
    phoneProvider: "org",
    "phone-service": "app",
    app: "registry",
    element: "registry",
    task: "registry",
    triggerParameter: "app",
    outputProperty: "app",
};
/**
 * Kinds the platform can update in place (PUT). A bound entity of any other
 * kind that has changed can't be updated — the deploy must surface that and
 * the user re-creates it. The reference-only kinds (field/cloudLink/connector) and app/element
 * self-refs never deploy through v2, so they're simply absent.
 *
 * `searchTable` is here but only *partially* updatable — the platform's PUT
 * only honors `duration`/`targetLag` on the snowflake variant (`warehouse` is
 * part of the DTO's shape but the platform doesn't apply changes to it, and
 * linked tables have no update surface at all). `planV2`
 * (`src/deploy/plan/plan.ts`) additionally checks that a search table's diff
 * only touches those fields before returning `"update"`; everything else
 * about a changed search table still routes to `"update-unsupported"`.
 *
 * `documentModel` has the same shape of caveat for its `excelCell` variant —
 * the graph's `documentModelUpdate` mutation has no update slot for its
 * `documentId`/`fields`, only `name`. `planV2` checks this the same way.
 */
export const REF_UPDATABLE = new Set([
    "automation",
    "agent",
    "agent-evaluation",
    "skill",
    "approvalChain",
    "table",
    "app",
    "element",
    "searchTable",
    "documentModel",
]);
